import os, re
def load_grids():
    d = os.environ.get('RLM_SESSION_DIR')
    if d:
        path = os.path.join(os.path.dirname(d), os.path.basename(d) + '.jsonl')
        path = path.replace('system/state', 'sessions')
        path = os.path.join(os.path.dirname(os.path.abspath(d)), 'sessions', os.path.basename(d) + '.jsonl')
    if not os.path.exists(path):
        # Try relative path from RLM_SESSION_DIR
        path = os.path.join(os.path.dirname(d), '../../sessions/' + os.path.basename(d) + '.jsonl')
    try:
        G = {}
        with open(path, 'r') as f:
            content = f.read().replace('\\n', '\n')
        for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
            k, h, w = m[1], int(m[2]), int(m[3])
            rows = [r.split() for r in content[m.end():].split('\n')[:h]]
            if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
                G[k] = [[int(x) for x in r] for r in rows]
        return G
    except:
        return {}
G = load_grids()
print("Loaded keys:", sorted(G.keys()))

